edges = {'fact': ['file', 'tool'], 'file': ['artifact'], 'tool': ['artifact'], 'artifact': []}
seen, frontier = set(['fact']), ['fact']
while frontier:
    cur = frontier.pop(0)
    for nxt in edges.get(cur, []):
        if nxt not in seen:
            seen.add(nxt); frontier.append(nxt)
print('reachable nodes:', len(seen))
print('nodes:', ', '.join(sorted(seen)))

